using System.Text.Json;

namespace EPaperDashboard.Services.Rendering;

/// <summary>
/// Loads and provides access to all Font Awesome solid icon SVG paths.
/// Icons are loaded from the <c>fa-icons.json</c> file generated by the
/// frontend build (via <c>generate-fa-icons.js</c>).
/// </summary>
public sealed class FontAwesomeIconRegistry
{
    private readonly Dictionary<string, IconEntry> _icons;
    private readonly ILogger<FontAwesomeIconRegistry> _logger;

    public record IconEntry(string Path, float VbW, float VbH);

    public FontAwesomeIconRegistry(
        IWebHostEnvironment env,
        ILogger<FontAwesomeIconRegistry> logger)
    {
        _logger = logger;
        _icons = LoadIcons(env);
    }

    /// <summary>
    /// Tries to retrieve the SVG path data for a Font Awesome icon.
    /// The <paramref name="name"/> can be with or without the "fa-" prefix.
    /// </summary>
    public bool TryGetIcon(string name, out IconEntry entry)
    {
        // Strip "fa-" prefix if present
        var key = name.StartsWith("fa-", StringComparison.OrdinalIgnoreCase)
            ? name[3..]
            : name;

        return _icons.TryGetValue(key, out entry!);
    }

    /// <summary>Total number of icons available in the registry.</summary>
    public int Count => _icons.Count;

    private Dictionary<string, IconEntry> LoadIcons(IWebHostEnvironment env)
    {
        var icons = new Dictionary<string, IconEntry>(StringComparer.OrdinalIgnoreCase);

        // The Angular build outputs to wwwroot/browser/ and copies public/ assets there.
        var jsonPath = Path.Combine(env.WebRootPath ?? "", "browser", "fa-icons.json");

        if (!File.Exists(jsonPath))
        {
            // Fallback: try directly in wwwroot (development proxy scenario)
            jsonPath = Path.Combine(env.WebRootPath ?? "", "fa-icons.json");
        }

        if (!File.Exists(jsonPath))
        {
            _logger.LogWarning(
                "Font Awesome icons file not found. " +
                "Icon rendering in SSR images will use built-in fallback icons. " +
                "Run the frontend build to generate fa-icons.json.");
            return LoadFallbackIcons();
        }

        try
        {
            var json = File.ReadAllText(jsonPath);
            using var doc = JsonDocument.Parse(json);

            foreach (var prop in doc.RootElement.EnumerateObject())
            {
                var path = prop.Value.GetProperty("path").GetString();
                var vbW = prop.Value.GetProperty("vbW").GetInt32();
                var vbH = prop.Value.GetProperty("vbH").GetInt32();

                if (!string.IsNullOrEmpty(path))
                    icons[prop.Name] = new IconEntry(path, vbW, vbH);
            }

            _logger.LogInformation("Loaded {Count} Font Awesome icons from {Path}", icons.Count, jsonPath);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to load Font Awesome icons from {Path}, using fallback", jsonPath);
            return LoadFallbackIcons();
        }

        return icons;
    }

